    {
      "rank": 1,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light turned a fundamental quantum limit into a practical tool for precision measurement, with major impact in gravitational-wave detection.",
        "attribution": "Caves established the quantum-noise framework, Kimble helped develop optical squeezing and its measurement applications, and Mavalvala led key interferometric demonstrations. The broader experimental effort was substantial.",
        "maturity": "The effect is well confirmed and now contributes to operating observatories, giving the work both experimental maturity and lasting use.",
        "uncertainties": [
          "The contribution spans theory, source development, and deployment across many researchers; selecting a small laureate group is difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B065",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping and enabled tests of fundamental physics and measurements of gravitational potential.",
        "attribution": "Katori and Ye independently pioneered the clock architectures and drove the experimental advances that made their extraordinary accuracy possible.",
        "maturity": "The clocks are repeatedly demonstrated in independent laboratories, with performance and applications continuing to improve.",
        "uncertainties": [
          "The field's progress depends on extensive community work in lasers, frequency combs, and optical standards."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Gerald Gabrielse",
        "Jeffrey Hangst",
        "Stefan Ulmer"
      ],
      "assessment": {
        "nobel_worthiness": "Trapping cold antimatter made precision spectroscopy and direct CPT tests possible, opening a distinctive experimental route to fundamental symmetry.",
        "attribution": "Gabrielse, Hangst, and Ulmer led complementary efforts in antiproton and antihydrogen trapping and in high-precision magnetic-moment measurements.",
        "maturity": "The trapping methods and precision measurements are firmly established, although the most sensitive symmetry tests remain in progress.",
        "uncertainties": [
          "The scientific achievement is distributed across large collaborations and distinct experimental programs."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "The theoretical foundations and trapped-ion demonstrations of quantum information processing created a durable framework for quantum simulation and computation.",
        "attribution": "Cirac and Zoller developed influential architectures and protocols; Blatt's experiments demonstrated control of trapped-ion systems and key quantum operations.",
        "maturity": "The foundational results are long confirmed, and trapped-ion control has advanced into increasingly capable multi-qubit systems.",
        "uncertainties": [
          "The eventual scope of fault-tolerant quantum computing remains unsettled, though the foundational physics is already consequential."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Ataç İmamoğlu",
        "Pascale Senellart",
        "Peter Michler"
      ],
      "assessment": {
        "nobel_worthiness": "On-demand semiconductor quantum-dot sources made deterministic single-photon generation practical and advanced quantum communication and photonic quantum technologies.",
        "attribution": "These researchers made complementary contributions to the concepts, materials, and experimental demonstrations of efficient, high-quality sources.",
        "maturity": "The sources are experimentally mature and have improved substantially in efficiency and indistinguishability, with continuing engineering challenges.",
        "uncertainties": [
          "The field includes many consequential advances in materials, device fabrication, and photon extraction beyond the nominated contributions."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry brought matter-wave coherence to precision measurement, enabling sensitive tests of gravity, inertia, and fundamental constants.",
        "attribution": "Bordé established early atom-optical interferometry, while Pritchard and Kasevich developed influential interferometer methods and precision experiments.",
        "maturity": "The technique is well established in laboratory measurements and continues to develop toward field use.",
        "uncertainties": [
          "The field's growth has involved many groups, and the relative weight of early foundations and later precision demonstrations is difficult to apportion."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Heino Falcke",
        "J. Anton Zensus",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Event Horizon Telescope imaging resolved horizon-scale structure around a black hole, providing a striking new test of strong-field gravity and a major advance in observational capability.",
        "attribution": "Falcke helped establish the scientific case, Zensus advanced the VLBI infrastructure and collaboration, and Doeleman led key observational efforts.",
        "maturity": "The images were produced with extensive cross-checks and later observations; the global-array method is now a demonstrated capability.",
        "uncertainties": [
          "The result depends on a large international collaboration, and the line between conceptual leadership, instrumentation, and data analysis is broad."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Ekkehard Peik",
        "Jun Ye",
        "Thorsten Schumm"
      ],
      "assessment": {
        "nobel_worthiness": "The thorium-229 nuclear transition offers a rare prospect for a nuclear clock and new tests of fundamental constants, with strong long-term potential.",
        "attribution": "Peik developed the nuclear-clock proposal and precision program; Ye and Schumm contributed important advances toward laser excitation and usable thorium systems.",
        "maturity": "The isomer transition has been directly observed and laser-excited, but a robust nuclear clock and its precision applications are still emerging.",
        "uncertainties": [
          "The central clock performance and its distinctive scientific reach have not yet been demonstrated at mature levels."
        ]
      }
    }
  ]
}
